    # is distance <=6?
    q=collections.deque([u]); dist={u:0}
    while q:
        x=q.popleft(); d=dist[x]
        if d>=maxd: continue
        for y in adj[x]:
            if y==v: return d+1
            if y not in dist:
                dist[y]=d+1; q.append(y)
    return None

